  <script>
    (() => {
      const root = document.currentScript?.closest('.wa-panel') ?? document.querySelector('.wa-panel');
      if (!root) return;
      const byId = id => root.querySelector(`#${id}`);
      const text = (id, value) => { const node = byId(id); if (node) node.textContent = value ?? '无'; };
      const asArray = value => Array.isArray(value) ? value : [];
      const clamp = value => Math.max(-100, Math.min(100, Number(value) || 0));

      function renderList(node, items, emptyText = '暂无') {
        node.replaceChildren();
        const values = asArray(items);
        if (!values.length) {
          const li = document.createElement('li');
          li.textContent = emptyText;
          li.className = 'wa-muted';
          node.append(li);
          return;
        }
        for (const item of values) {
          const li = document.createElement('li');
          li.textContent = String(item);
          node.append(li);
        }
      }

      function relationWord(value, positive = true) {
        const score = clamp(value);
        if (!positive) {
          if (score >= 65) return '高度';
          if (score >= 30) return '明显';
          if (score > 0) return '轻微';
          return '无';
        }
        if (score >= 65) return '深厚';
        if (score >= 30) return '稳定';
        if (score > 0) return '初步';
        if (score <= -30) return '破裂';
        if (score < 0) return '疏离';
        return '未建立';
      }

      function makeMeter(label, value, negative = false) {
        const score = clamp(value);
        const row = document.createElement('div');
        row.className = 'wa-meter-row';
        const name = document.createElement('span');
        name.textContent = label;
        const track = document.createElement('span');
        track.className = 'wa-meter';
        const fill = document.createElement('span');
        fill.dataset.negative = String(negative || score < 0);
        fill.style.left = score < 0 ? `${50 + score / 2}%` : '50%';
        fill.style.width = `${Math.abs(score) / 2}%`;
        track.append(fill);
        const words = document.createElement('span');
        words.className = 'wa-meter-text';
        words.textContent = `${score} · ${relationWord(Math.abs(score), negative)}`;
        row.append(name, track, words);
        return row;
      }

      function renderRelations(relations) {
        const container = byId('wa-relations');
        container.replaceChildren();
        const unlocked = Object.entries(relations ?? {}).filter(([, relation]) => relation?.解锁);
        if (!unlocked.length) {
          const empty = document.createElement('p');
          empty.className = 'wa-muted';
          empty.textContent = '尚无人物解锁。';
          container.append(empty);
          return;
        }
        for (const [name, relation] of unlocked) {
          const details = document.createElement('details');
          details.className = 'wa-person';
          const summary = document.createElement('summary');
          const heading = document.createElement('span');
          heading.className = 'wa-name';
          heading.textContent = name;
          const status = document.createElement('span');
          status.className = 'wa-status';
          status.textContent = `${relation.生存状态 ?? '状态未知'}${relation.在场 ? ' · 在场' : ''}`;
          summary.append(heading, status);

          const body = document.createElement('div');
          body.className = 'wa-person-body';
          const meta = document.createElement('p');
          meta.className = 'wa-person-meta';
          meta.textContent = `${relation.关系类型 ?? '关系未明'}｜${relation.人物阶段 ?? '阶段未明'}｜${relation.位置 ?? '位置未知'}`;
          const situation = document.createElement('p');
          situation.className = 'wa-value';
          situation.textContent = relation.处境 ?? '处境未知';
          const hasContact = relation.最近互动 && relation.最近互动 !== '无';
          if (hasContact) {
            body.append(meta, situation);
            body.append(
              makeMeter('信任', relation.信任),
              makeMeter('亲近', relation.亲近),
              makeMeter('戒备', relation.戒备, true),
              makeMeter('吸引', relation.吸引),
              makeMeter('创伤', relation.关系创伤, true)
            );
            const cue = document.createElement('p');
            cue.className = 'wa-muted';
            cue.textContent = `最近互动：${relation.最近互动}`;
            body.append(cue);
          } else {
            const locked = document.createElement('p');
            locked.className = 'wa-muted';
            locked.textContent = '尚无实际接触，仅显示姓名与状态。';
            body.append(locked);
          }
          details.append(summary, body);
          container.append(details);
        }
      }

      function renderEdges(edges) {
        const container = byId('wa-edges');
        container.replaceChildren();
        const values = asArray(edges);
        if (!values.length) {
          const empty = document.createElement('p');
          empty.className = 'wa-muted';
          empty.textContent = '尚无需要长期记录的角色关系。';
          container.append(empty);
          return;
        }
        for (const edge of values) {
          const row = document.createElement('div');
          row.className = 'wa-edge';
          const title = document.createElement('p');
          title.className = 'wa-value';
          title.textContent = `${asArray(edge.双方).join(' ↔ ')}｜${edge.关系类型 ?? '关系未明'}`;
          const detail = document.createElement('p');
          detail.className = 'wa-value wa-muted';
          detail.textContent = `${edge.当前状态 ?? '状态未明'}｜${edge.公开程度 ?? '公开程度未明'}｜${edge.最近变化 ?? '暂无变化'}`;
          row.append(title, detail);
          container.append(row);
        }
      }

      function updateUrgency(card, urgency) {
        card.classList.toggle('wa-card--urgent', urgency === '高' || urgency === '极高');
      }

      function render(data) {
        const state = data?.stat_data;
        if (!state) throw new Error('当前楼层还没有初始化变量');
        const world = state.世界 ?? {};
        const linen = state.林恩 ?? {};
        const system = state.系统 ?? {};
        const events = state.事件 ?? {};
        const active = events.唯一活跃事件 ?? {};
        const omen = events.近期预兆 ?? {};

        text('wa-phase', `${world.阶段编号 ?? '未知'} · ${world.阶段名称 ?? '阶段未知'}`);
        text('wa-phase-progress', `${world.模糊阶段进度 ?? '进度未知'}｜${world.氛围 ?? '氛围未知'}`);
        text('wa-location', world.地点);
        text('wa-time', world.当前场景时间);
        text('wa-linen', `20岁｜${linen.身体状况 ?? '身体状况未知'}`);
        const identityBox = byId('wa-identities');
        identityBox.replaceChildren();
        for (const identity of asArray(linen.当前身份)) {
          const chip = document.createElement('span');
          chip.className = 'wa-chip';
          chip.textContent = identity;
          identityBox.append(chip);
        }
        text('wa-task', `${system.当前任务 ?? '无'}｜${system.任务状态 ?? '无'}`);
        text('wa-task-note', `${linen.当前明确目标 ?? '目标未明确'}｜${system.任务说明 ?? '无说明'}`);
        text('wa-current-event', `${active.事件ID || '无'} ${active.标题 || '暂无活跃事件'}｜${active.紧迫度 ?? '无'}`);
        text('wa-current-event-progress', `${active.地点 ?? '地点未知'}｜${active.模糊期限 ?? '期限未知'}｜${active.进展 ?? '暂无进展'}`);
        updateUrgency(byId('wa-current-event-card'), active.紧迫度);

        renderRelations(state.关系);
        renderEdges(state.角色关系);

        text('wa-event-title', `${active.事件ID || '无'} ${active.标题 || '暂无活跃事件'}｜${active.状态 ?? '无'}｜紧迫度 ${active.紧迫度 ?? '无'}`);
        text('wa-event-detail', `${active.地点 ?? '地点未知'}｜参与者：${asArray(active.参与者).join('、') || '未知'}｜${active.模糊期限 ?? '期限未知'}｜${active.进展 ?? '暂无进展'}`);
        updateUrgency(byId('wa-event-detail-card'), active.紧迫度);

        text('wa-omen-title', `${omen.事件ID || '无预兆'}｜${omen.紧迫度 ?? '无'}`);
        text('wa-omen-detail', `${omen.方向 ?? '暂无'}｜${omen.地点 ?? '地点未知'}｜${omen.模糊期限 ?? '期限未知'}`);
        renderList(
          byId('wa-results'),
